#include <algorithm>
#include <cmath>
#include <iostream>
#include <memory>
#include <optional>
#include <sstream>
#include <string>
#include <utility>
#include <vector>

class OrderedDict
{
public:
    using Entry = std::pair<std::string, long long>;

    bool set(const std::string& key, long long value) { return insert(root_, key, value); }   // true if added
    bool erase(const std::string& key) { return erase(root_, key); }

    std::optional<long long> get(const std::string& key) const
    {
        const Node* n = root_.get();
        while (n && n->key != key) n = key < n->key ? n->left.get() : n->right.get();
        if (!n) return std::nullopt;
        return n->value;
    }

    std::size_t size() const { return sizeOf(root_); }
    int height() const { return heightOf(root_); }

    std::optional<Entry> floor(const std::string& word) const
    {
        std::optional<Entry> best;
        for (const Node* n = root_.get(); n;)
        {
            if (n->key <= word) { best = Entry{ n->key, n->value }; n = n->right.get(); }
            else n = n->left.get();
        }
        return best;
    }

    std::optional<Entry> ceil(const std::string& word) const
    {
        std::optional<Entry> best;
        for (const Node* n = root_.get(); n;)
        {
            if (n->key >= word) { best = Entry{ n->key, n->value }; n = n->left.get(); }
            else n = n->right.get();
        }
        return best;
    }

    // Number and sum of the keys below `word` (or at most `word` when inclusive).
    std::pair<std::size_t, long long> below(const std::string& word, bool inclusive) const
    {
        std::size_t count = 0;
        long long sum = 0;
        for (const Node* n = root_.get(); n;)
        {
            bool goRight = inclusive ? n->key <= word : n->key < word;
            if (goRight)
            {
                count += sizeOf(n->left) + 1;
                sum += sumOf(n->left) + n->value;
                n = n->right.get();
            }
            else n = n->left.get();
        }
        return { count, sum };
    }

    std::optional<Entry> nth(std::size_t k) const      // from 0
    {
        if (k >= size()) return std::nullopt;
        const Node* n = root_.get();
        while (true)
        {
            std::size_t left = sizeOf(n->left);
            if (k < left) n = n->left.get();
            else if (k == left) return Entry{ n->key, n->value };
            else { k -= left + 1; n = n->right.get(); }
        }
    }

    std::vector<Entry> range(const std::string& lo, const std::string& hi) const
    {
        std::vector<Entry> out;
        collect(root_.get(), lo, hi, out);
        return out;
    }

private:
    struct Node
    {
        std::string key;
        long long value;
        int height = 0;
        std::size_t size = 1;
        long long sum;
        std::unique_ptr<Node> left, right;
    };

    static int heightOf(const std::unique_ptr<Node>& n) { return n ? n->height : -1; }
    static std::size_t sizeOf(const std::unique_ptr<Node>& n) { return n ? n->size : 0; }
    static long long sumOf(const std::unique_ptr<Node>& n) { return n ? n->sum : 0; }

    static void update(Node& n)
    {
        n.height = 1 + std::max(heightOf(n.left), heightOf(n.right));
        n.size = 1 + sizeOf(n.left) + sizeOf(n.right);
        n.sum = n.value + sumOf(n.left) + sumOf(n.right);
    }

    static int balance(const Node& n) { return heightOf(n.left) - heightOf(n.right); }

    static void rotateRight(std::unique_ptr<Node>& link)
    {
        std::unique_ptr<Node> x = std::move(link->left);
        link->left = std::move(x->right);
        update(*link);
        x->right = std::move(link);
        update(*x);
        link = std::move(x);
    }

    static void rotateLeft(std::unique_ptr<Node>& link)
    {
        std::unique_ptr<Node> x = std::move(link->right);
        link->right = std::move(x->left);
        update(*link);
        x->left = std::move(link);
        update(*x);
        link = std::move(x);
    }

    static void rebalance(std::unique_ptr<Node>& link)
    {
        update(*link);
        int b = balance(*link);
        if (b > 1)
        {
            if (balance(*link->left) < 0) rotateLeft(link->left);
            rotateRight(link);
        }
        else if (b < -1)
        {
            if (balance(*link->right) > 0) rotateRight(link->right);
            rotateLeft(link);
        }
    }

    static bool insert(std::unique_ptr<Node>& link, const std::string& key, long long value)
    {
        if (!link)
        {
            link = std::make_unique<Node>();
            link->key = key;
            link->value = value;
            link->sum = value;
            return true;
        }
        bool added = false;
        if (key == link->key) link->value = value;
        else added = insert(key < link->key ? link->left : link->right, key, value);
        rebalance(link);                                  // also refreshes the sum after an update
        return added;
    }

    static Node takeMin(std::unique_ptr<Node>& link)     // removes the smallest node below link, returns its key and value
    {
        if (!link->left)
        {
            Node out;
            out.key = std::move(link->key);
            out.value = link->value;
            link = std::move(link->right);
            return out;
        }
        Node out = takeMin(link->left);
        rebalance(link);
        return out;
    }

    static bool erase(std::unique_ptr<Node>& link, const std::string& key)
    {
        if (!link) return false;
        if (key < link->key) { if (!erase(link->left, key)) return false; }
        else if (key > link->key) { if (!erase(link->right, key)) return false; }
        else if (!link->left) { link = std::move(link->right); return true; }
        else if (!link->right) { link = std::move(link->left); return true; }
        else
        {
            Node successor = takeMin(link->right);
            link->key = std::move(successor.key);
            link->value = successor.value;
        }
        rebalance(link);
        return true;
    }

    static void collect(const Node* n, const std::string& lo, const std::string& hi, std::vector<Entry>& out)
    {
        if (!n) return;
        if (lo < n->key) collect(n->left.get(), lo, hi, out);
        if (lo <= n->key && n->key <= hi) out.push_back({ n->key, n->value });
        if (n->key < hi) collect(n->right.get(), lo, hi, out);
    }

    std::unique_ptr<Node> root_;
};

static std::optional<long long> parseNumber(const std::string& s, long long low, long long high)
{
    std::size_t i = (s.size() > 1 && s[0] == '-') ? 1 : 0;
    if (i == s.size() || s.size() - i > 13) return std::nullopt;
    for (std::size_t k = i; k < s.size(); ++k)
        if (s[k] < '0' || s[k] > '9') return std::nullopt;
    long long n = std::stoll(s);
    if (n < low || n > high) return std::nullopt;
    return n;
}

static std::string show(const std::optional<OrderedDict::Entry>& e, const char* none)
{
    return e ? e->first + " = " + std::to_string(e->second) : none;
}

static std::string keysAndSum(std::size_t count, long long sum)
{
    if (count == 0) return "0 keys";
    return std::to_string(count) + (count == 1 ? " key" : " keys") + ", sum " + std::to_string(sum);
}

int main()
{
    OrderedDict dict;
    const std::vector<std::pair<std::string, std::string>> usage{
        { "set", "set <key> <value>" }, { "get", "get <key>" }, { "del", "del <key>" }, { "min", "min" }, { "max", "max" },
        { "floor", "floor <word>" }, { "ceil", "ceil <word>" }, { "rank", "rank <word>" }, { "nth", "nth <i>" },
        { "range", "range <lo> <hi>" }, { "count", "count <lo> <hi>" }, { "size", "size" }, { "bulk", "bulk <prefix> <n>" }, { "check", "check" } };
    const long long limit = 1000000000000LL;

    std::string line;
    while (std::getline(std::cin, line))
    {
        std::istringstream in(line);
        std::vector<std::string> w;
        for (std::string word; in >> word;) w.push_back(word);
        if (w.empty()) continue;

        auto known = std::find_if(usage.begin(), usage.end(), [&](const auto& u) { return u.first == w[0]; });
        if (known == usage.end())
        {
            std::cout << "error: unknown command '" << w[0] << "'\n";
            continue;
        }
        std::size_t words = static_cast<std::size_t>(std::count(known->second.begin(), known->second.end(), ' ')) + 1;
        if (w.size() != words)
        {
            std::cout << "error: usage: " << known->second << '\n';
            continue;
        }

        const std::string& cmd = w[0];
        if (cmd == "set")
        {
            auto value = parseNumber(w[2], -limit, limit);
            if (!value) { std::cout << "error: the value must be a whole number from -1000000000000 to 1000000000000\n"; continue; }
            std::cout << (dict.set(w[1], *value) ? "added " : "updated ") << w[1] << '\n';
        }
        else if (cmd == "get")
        {
            auto v = dict.get(w[1]);
            std::cout << (v ? std::to_string(*v) : "not found") << '\n';
        }
        else if (cmd == "del") std::cout << (dict.erase(w[1]) ? "deleted " + w[1] : std::string("not found")) << '\n';
        else if (cmd == "min") std::cout << show(dict.nth(0), "empty") << '\n';
        else if (cmd == "max") std::cout << show(dict.size() ? dict.nth(dict.size() - 1) : std::nullopt, "empty") << '\n';
        else if (cmd == "floor") std::cout << show(dict.floor(w[1]), "none") << '\n';
        else if (cmd == "ceil") std::cout << show(dict.ceil(w[1]), "none") << '\n';
        else if (cmd == "rank") std::cout << dict.below(w[1], false).first << '\n';
        else if (cmd == "nth")
        {
            auto i = parseNumber(w[1], 1, static_cast<long long>(dict.size()));
            if (!i) std::cout << "error: there is no key number " << w[1] << '\n';
            else std::cout << show(dict.nth(static_cast<std::size_t>(*i - 1)), "") << '\n';
        }
        else if (cmd == "range")
        {
            auto entries = w[1] <= w[2] ? dict.range(w[1], w[2]) : std::vector<OrderedDict::Entry>{};
            long long sum = 0;
            for (const auto& e : entries) sum += e.second;
            std::cout << keysAndSum(entries.size(), sum);
            for (std::size_t i = 0; i < entries.size(); ++i) std::cout << (i ? ", " : ": ") << entries[i].first << '=' << entries[i].second;
            std::cout << '\n';
        }
        else if (cmd == "count")
        {
            if (w[1] > w[2]) { std::cout << "0 keys\n"; continue; }
            auto [upCount, upSum] = dict.below(w[2], true);
            auto [loCount, loSum] = dict.below(w[1], false);
            std::cout << keysAndSum(upCount - loCount, upSum - loSum) << '\n';
        }
        else if (cmd == "size") std::cout << dict.size() << '\n';
        else if (cmd == "bulk")
        {
            auto n = parseNumber(w[2], 1, 100000);
            if (!n) { std::cout << "error: n must be from 1 to 100000\n"; continue; }
            long long added = 0;
            for (long long i = 1; i <= *n; ++i)
            {
                std::string digits = std::to_string(i);
                added += dict.set(w[1] + std::string(6 - digits.size(), '0') + digits, i);
            }
            std::cout << "bulk: " << added << " added, " << (*n - added) << " updated\n";
        }
        else
        {
            int h = dict.height();
            if (h <= 2 * std::log2(static_cast<double>(dict.size()) + 1)) std::cout << "balanced\n";
            else std::cout << "not balanced (height " << h << ")\n";
        }
    }
}
